    readonly claims: ReadonlyArray<Uint8Array<ArrayBuffer>>;
};
/** One serializable claim result. @public */
export type GeoSpecClaimResult = {
    readonly claimId: GeoSpecClaimId;
    readonly status: 'passed' | 'failed' | 'refused' | 'cancelled';
