 *
 * @public
 */
export type SelectorFaceFacts = {
    faceIndex: number;
    surfaceType: SelectorSurfaceType;
    normal?: Vec3;
    offset?: number;
    axisOrigin?: Vec3;
    axisDirection?: Vec3;
    radius?: number;
    area: number;
    centroid: Vec3;
